parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('Contract intake agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize intake').item.json;
const queue = cfg.queue_by_type?.[out?.contract_type] ?? null;
const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '').replace(/(inc|llc|ltd|limited|corp|corporation|gmbh|plc)$/, '');

if (!queue) reasons.push('no queue mapped for contract type ' + out?.contract_type);
if (queue && out?.suggested_queue !== queue) reasons.push('agent suggests ' + out?.suggested_queue + ', routing map says ' + queue);
if (req.counterparty_stated && out?.counterparty_name && norm(req.counterparty_stated) !== norm(out.counterparty_name)) {
  reasons.push('requester named "' + req.counterparty_stated + '", contract says "' + out.counterparty_name + '"');
}

const ok = reasons.length === 0;
return {
  json: {
    business_key: req.business_key,
    route: ok ? 'auto' : 'escalate',
    guardrail_reasons: reasons,
    queue,
    priority: out?.risk_tier === 'high' ? 'high' : 'normal',
    planned_actions: ok ? [{ action: 'clm.create_matter', queue, risk_tier: out.risk_tier }] : [],
  },
};

const g = $('Guardrails').item.json;
const ok = !!$json.id && $json.queue === g.queue && $json.external_ref === $('Normalize intake').item.json.intake_id;
return {
  json: {
    verified: ok,
    verify_failed: !ok,
    verify_detail: ok ? '' : 'CLM matter does not match the planned queue or reference',
    matter_id: $json.id,
    queue: $json.queue,
  },
};

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize intake').item.json;
let agent = null;
let guard = null;
try { agent = $('Contract intake agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "legal triage",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'Intake ' + intake.intake_id + ' from ' + intake.requester_name + ' · ' + (agent?.output?.contract_type ?? 'unclassified') + ' · counterparty ' + (agent?.output?.counterparty_name ?? intake.counterparty_stated ?? 'unknown'),
  },
};

